
/* ==========================================================================
   StockMarketDB — Βάση δεδομένων μαθήματος
   «Βάσεις Δεδομένων και Επιχειρηματική Αναλυτική» · Πανεπιστήμιο Πειραιώς
   Δρ. Αθανάσιος Κρανιάς · Χειμερινό εξάμηνο 2026–27

   ΣΗΜΑΝΤΙΚΟ: Όλες οι εταιρείες και τα δεδομένα είναι ΦΑΝΤΑΣΤΙΚΑ (συνθετικά),
   για εκπαιδευτική χρήση. Οποιαδήποτε ομοιότητα με πραγματικές εταιρείες
   είναι συμπτωματική.

   Εκτέλεση: SSMS → New Query → επικόλληση → Execute (F5).
   Απαιτεί SQL Server 2016 ή νεότερο.
   ========================================================================== */

USE master;
GO
DROP DATABASE IF EXISTS StockMarketDB;
GO
CREATE DATABASE StockMarketDB;
GO
USE StockMarketDB;
GO

/* ---------- Κλάδοι ---------- */
CREATE TABLE Sectors (
    SectorID    INT           NOT NULL PRIMARY KEY,
    SectorName  NVARCHAR(50)  NOT NULL UNIQUE
);

/* ---------- Εισηγμένες εταιρείες ---------- */
CREATE TABLE Companies (
    CompanyID    INT            NOT NULL PRIMARY KEY,
    Ticker       VARCHAR(10)    NOT NULL UNIQUE,
    CompanyName  NVARCHAR(100)  NOT NULL,
    SectorID     INT            NOT NULL REFERENCES Sectors(SectorID),
    Country      NVARCHAR(50)   NOT NULL DEFAULT N'Ελλάδα',
    FoundedYear  SMALLINT       CHECK (FoundedYear BETWEEN 1800 AND 2100),
    Employees    INT            CHECK (Employees >= 0),   -- NULL = δεν έχει δημοσιευθεί
    ListingDate  DATE           NOT NULL
);

/* ---------- Ημερήσιες τιμές μετοχών ---------- */
CREATE TABLE StockPrices (
    CompanyID   INT            NOT NULL REFERENCES Companies(CompanyID),
    TradeDate   DATE           NOT NULL,
    OpenPrice   DECIMAL(10,2)  NOT NULL,
    HighPrice   DECIMAL(10,2)  NOT NULL,
    LowPrice    DECIMAL(10,2)  NOT NULL,
    ClosePrice  DECIMAL(10,2)  NOT NULL,
    Volume      BIGINT         NOT NULL CHECK (Volume >= 0),
    CONSTRAINT PK_StockPrices PRIMARY KEY (CompanyID, TradeDate),
    CONSTRAINT CK_HighLow CHECK (HighPrice >= LowPrice)
);

/* ---------- Γενικός δείκτης αγοράς ---------- */
CREATE TABLE MarketIndex (
    TradeDate   DATE           NOT NULL PRIMARY KEY,
    IndexClose  DECIMAL(12,2)  NOT NULL
);

/* ---------- Ετήσια οικονομικά στοιχεία (σε εκατ. €) ---------- */
CREATE TABLE Financials (
    CompanyID    INT            NOT NULL REFERENCES Companies(CompanyID),
    FiscalYear   SMALLINT       NOT NULL,
    Revenue      DECIMAL(18,2)  NOT NULL,
    NetIncome    DECIMAL(18,2)  NULL,          -- NULL = δεν έχει ανακοινωθεί
    TotalAssets  DECIMAL(18,2)  NOT NULL,
    TotalDebt    DECIMAL(18,2)  NOT NULL,
    Equity       DECIMAL(18,2)  NOT NULL,
    CONSTRAINT PK_Financials PRIMARY KEY (CompanyID, FiscalYear)
);

/* ---------- Μερίσματα ---------- */
CREATE TABLE Dividends (
    DividendID      INT            NOT NULL PRIMARY KEY,
    CompanyID       INT            NOT NULL REFERENCES Companies(CompanyID),
    ExDate          DATE           NOT NULL,
    AmountPerShare  DECIMAL(10,3)  NOT NULL CHECK (AmountPerShare > 0)
);
GO

/* ---------- Δεδομένα ---------- */
GO

/* ---------- Έλεγχος: πόσες γραμμές έχει κάθε πίνακας ---------- */
SELECT 'Sectors' AS TableName, COUNT(*) AS NumRows FROM Sectors
UNION ALL SELECT 'Companies',   COUNT(*) FROM Companies
UNION ALL SELECT 'StockPrices', COUNT(*) FROM StockPrices
UNION ALL SELECT 'MarketIndex', COUNT(*) FROM MarketIndex
UNION ALL SELECT 'Financials',  COUNT(*) FROM Financials
UNION ALL SELECT 'Dividends',   COUNT(*) FROM Dividends;
